{"filePath":"/tmp/opencode/rename_csv.py","content":"import os
import sys

d = sys.argv[1]
files = [
    f for f in os.listdir(d)
    if f.lower().endswith('.csv') and os.path.isfile(os.path.join(d, f))
]
files.sort(key=lambda f: (os.path.getsize(os.path.join(d, f)), f))

for i, f in enumerate(files):
    size = os.path.getsize(os.path.join(d, f))
    os.rename(os.path.join(d, f), os.path.join(d, '.tmp_rename_%d' % i))
    print('%s (%d bytes) -> %d.csv' % (f, size, i))

for i in range(len(files)):
    os.rename(os.path.join(d, '.tmp_rename_%d' % i), os.path.join(d, '%d.csv' % i))

print('done: %d files renamed' % len(files))
"}
